export const cleanupScopes={orders:'Pedidos de vídeos',sponsors:'Empresas arquivadas',community:'Comunidade',live:'LIVE',trash:'Lixeira',reports:'Relatórios com mais de 30 dias',visits:'Aberturas de páginas com mais de 30 dias'};
export function cleanupIds(data,scope,filter='all'){
 const orders=(data.orders||[]).filter(o=>filter==='all'||filter==='review'&&o.review==='pending'||filter==='queue'&&o.review==='approved'&&o.payment==='confirmed'&&o.delivery==='waiting'&&!o.payment_hold||filter==='refund'&&o.review==='rejected'&&o.payment==='confirmed'||filter==='published'&&o.delivery==='published');
 return [...new Set((scope==='orders'?orders:scope==='sponsors'?data.sponsors||[]:scope==='trash'?[...(data.trashOrders||[]),...(data.trashSponsors||[])]:['community','live'].includes(scope)?(data.communityMessages||[]).filter(o=>(o.destination||'community')===scope):[]).map(x=>x.id))].slice(0,1000);
}
export function cleanupDialog(scopes){return `<h2>Limpar dados</h2><p>Confira a quantidade antes de excluir definitivamente. Não é necessário preencher justificativa.</p><form><div class="field"><label for="cleanup-scope">Área</label><select id="cleanup-scope" name="scope">${scopes.map(scope=>`<option value="${scope}">${cleanupScopes[scope]}</option>`).join('')}</select></div><p class="hint">IP, nome e telefone ainda no prazo de 48 horas ficam no registro privado e não são excluídos por esta ferramenta. Registros financeiros, publicações ativas e pedidos com entrega ou devolução pendente são preservados. O conteúdo de mensagens pagas já encerradas pode ser excluído. Pedidos de vídeos e empresas precisam estar na Lixeira. Relatórios e acessos preservam os últimos 30 dias. Até 1000 registros carregados por operação.</p><p id="cleanup-preview" role="status"></p><p class="error" role="alert"></p><button class="btn secondary" type="button" id="cleanup-check">Conferir quantidade</button> <button class="btn danger" type="submit" disabled>Excluir definitivamente</button></form>`}
